shopify.query:
query AdsHeartbeatNewOrderCounts {
 shop { id name ianaTimezone }
 allNew: ordersCount(query: "created_at:>'2026-09-11T21:21:23Z' created_at:<'2026-09-11T22:48:55Z'", limit: null) { count precision }
 webNonTest: ordersCount(query: "created_at:>'2026-09-11T21:21:23Z' created_at:<'2026-09-11T22:48:55Z' source_name:web test:false", limit: null) { count precision }
 paidWebNonTest: ordersCount(query: "created_at:>'2026-09-11T21:21:23Z' created_at:<'2026-09-11T22:48:55Z' source_name:web test:false financial_status:paid", limit: null) { count precision }
}
